CREATE SCHEMA IF NOT EXISTS study_track;
-- H2 mirror of src/main/resources/db/migration. Flyway is off in tests; update this with every migration.
-- V1__create_users.sql
CREATE TABLE study_track.users (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 2) PRIMARY KEY, display_name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, is_admin BOOLEAN NOT NULL DEFAULT FALSE, CONSTRAINT uq_users_email UNIQUE (email));
INSERT INTO study_track.users (id, display_name, email, is_admin) VALUES (1, 'Default user', 'default-user@study-track.local', TRUE);
-- V2__create_subjects_topics.sql (TEXT columns are VARCHAR here so Hibernate validation sees the same type as PostgreSQL)
CREATE TABLE study_track.subjects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), name VARCHAR(120) NOT NULL, description VARCHAR(1000), icon VARCHAR(16), sort_order INT NOT NULL DEFAULT 0, archived BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_subjects_user_name UNIQUE (user_id, name));
CREATE TABLE study_track.topics (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subject_id BIGINT NOT NULL REFERENCES study_track.subjects (id) ON DELETE CASCADE, parent_id BIGINT REFERENCES study_track.topics (id) ON DELETE CASCADE, name VARCHAR(200) NOT NULL, description_html VARCHAR(1000000), sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_topics_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id));
CREATE INDEX idx_topics_subject_id ON study_track.topics (subject_id);
CREATE INDEX idx_topics_parent_id ON study_track.topics (parent_id);
-- V3__create_items.sql
CREATE TABLE study_track.questions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, topic_id BIGINT NOT NULL REFERENCES study_track.topics (id) ON DELETE CASCADE, subject_id BIGINT NOT NULL REFERENCES study_track.subjects (id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES study_track.users (id), question_type VARCHAR(20) NOT NULL, title VARCHAR(300) NOT NULL, question_html VARCHAR(1000000), answer_html VARCHAR(1000000), notes_html VARCHAR(1000000), answer_plain_text VARCHAR(1000000), difficulty VARCHAR(10) NOT NULL DEFAULT 'MEDIUM', source VARCHAR(10) NOT NULL DEFAULT 'MANUAL', import_job_id BIGINT, content_hash VARCHAR(64), sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_questions_type CHECK (question_type IN ('QUESTION', 'NOTE', 'EXAMPLE', 'DIAGRAM')), CONSTRAINT ck_questions_difficulty CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')), CONSTRAINT ck_questions_source CHECK (source IN ('MANUAL', 'IMPORT')));
CREATE INDEX idx_questions_topic_id ON study_track.questions (topic_id);
CREATE INDEX idx_questions_content_hash ON study_track.questions (content_hash);
CREATE TABLE study_track.tags (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), name VARCHAR(50) NOT NULL, CONSTRAINT uq_tags_user_name UNIQUE (user_id, name));
CREATE TABLE study_track.question_tags (question_id BIGINT NOT NULL REFERENCES study_track.questions (id) ON DELETE CASCADE, tag_id BIGINT NOT NULL REFERENCES study_track.tags (id) ON DELETE CASCADE, CONSTRAINT pk_question_tags PRIMARY KEY (question_id, tag_id));
CREATE INDEX idx_question_tags_tag_id ON study_track.question_tags (tag_id);
-- V4__create_media.sql
CREATE TABLE study_track.media_files (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), question_id BIGINT REFERENCES study_track.questions (id) ON DELETE SET NULL, original_name VARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL, size_bytes BIGINT NOT NULL, storage_key VARCHAR(500) NOT NULL, width INT, height INT, alt_text VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_media_files_storage_key UNIQUE (storage_key), CONSTRAINT ck_media_files_size CHECK (size_bytes > 0));
CREATE INDEX idx_media_files_user_id ON study_track.media_files (user_id);
CREATE INDEX idx_media_files_item_id ON study_track.media_files (question_id);
-- V5__create_progress.sql
CREATE TABLE study_track.question_progress (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), question_id BIGINT NOT NULL REFERENCES study_track.questions (id) ON DELETE CASCADE, status VARCHAR(20) NOT NULL DEFAULT 'NOT_STARTED', confidence SMALLINT, review_count INT NOT NULL DEFAULT 0, last_reviewed_at TIMESTAMP, next_review_at TIMESTAMP, bookmarked BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_question_progress_user_question UNIQUE (user_id, question_id), CONSTRAINT ck_question_progress_status CHECK (status IN ('NOT_STARTED', 'LEARNING', 'DONE')), CONSTRAINT ck_question_progress_confidence CHECK (confidence IS NULL OR confidence BETWEEN 1 AND 5), CONSTRAINT ck_question_progress_review_count CHECK (review_count >= 0));
CREATE INDEX idx_question_progress_item_id ON study_track.question_progress (question_id);
CREATE INDEX idx_question_progress_user_next_review ON study_track.question_progress (user_id, next_review_at);
CREATE TABLE study_track.topic_progress (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), topic_id BIGINT NOT NULL REFERENCES study_track.topics (id) ON DELETE CASCADE, completed BOOLEAN NOT NULL DEFAULT FALSE, completed_at TIMESTAMP, CONSTRAINT uq_topic_progress_user_topic UNIQUE (user_id, topic_id));
CREATE INDEX idx_topic_progress_topic_id ON study_track.topic_progress (topic_id);
CREATE TABLE study_track.flashcard_reviews (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), question_id BIGINT NOT NULL REFERENCES study_track.questions (id) ON DELETE CASCADE, result VARCHAR(10) NOT NULL, reviewed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_flashcard_reviews_result CHECK (result IN ('AGAIN', 'HARD', 'GOOD', 'EASY')));
CREATE INDEX idx_flashcard_reviews_user_reviewed_at ON study_track.flashcard_reviews (user_id, reviewed_at);
CREATE INDEX idx_flashcard_reviews_item_id ON study_track.flashcard_reviews (question_id, reviewed_at);
CREATE TABLE study_track.resume_points (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), subject_id BIGINT NOT NULL REFERENCES study_track.subjects (id) ON DELETE CASCADE, last_topic_id BIGINT REFERENCES study_track.topics (id) ON DELETE SET NULL, last_question_id BIGINT REFERENCES study_track.questions (id) ON DELETE SET NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_resume_points_user_subject UNIQUE (user_id, subject_id));
CREATE INDEX idx_resume_points_user_updated_at ON study_track.resume_points (user_id, updated_at);
-- V6__create_import.sql
CREATE TABLE study_track.import_jobs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), subject_id BIGINT NOT NULL REFERENCES study_track.subjects (id) ON DELETE CASCADE, file_name VARCHAR(255) NOT NULL, file_type VARCHAR(10) NOT NULL, uploaded_file_id BIGINT REFERENCES study_track.media_files (id) ON DELETE SET NULL, status VARCHAR(20) NOT NULL DEFAULT 'UPLOADED', llm_provider VARCHAR(20), llm_model VARCHAR(100), total_chunks INT NOT NULL DEFAULT 0, processed_chunks INT NOT NULL DEFAULT 0, failed_chunks INT NOT NULL DEFAULT 0, input_tokens BIGINT NOT NULL DEFAULT 0, output_tokens BIGINT NOT NULL DEFAULT 0, error_message VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_import_jobs_file_type CHECK (file_type IN ('DOCX', 'PDF', 'MD', 'TXT', 'CSV')), CONSTRAINT ck_import_jobs_status CHECK (status IN ('UPLOADED', 'PARSING', 'EXTRACTING', 'READY_FOR_REVIEW', 'COMPLETED', 'FAILED')), CONSTRAINT ck_import_jobs_provider CHECK (llm_provider IN ('ANTHROPIC', 'OPENAI', 'GROQ', 'OLLAMA')));
CREATE INDEX idx_import_jobs_user_created_at ON study_track.import_jobs (user_id, created_at);
CREATE INDEX idx_import_jobs_subject_id ON study_track.import_jobs (subject_id);
CREATE TABLE study_track.import_drafts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, import_job_id BIGINT NOT NULL REFERENCES study_track.import_jobs (id) ON DELETE CASCADE, chunk_index INT NOT NULL, suggested_topic_path VARCHAR(500), question_type VARCHAR(20) NOT NULL, title VARCHAR(300) NOT NULL, question_html VARCHAR(1000000), answer_html VARCHAR(1000000), notes_html VARCHAR(1000000), difficulty VARCHAR(10) NOT NULL DEFAULT 'MEDIUM', tags VARCHAR(1000), image_media_ids VARCHAR(1000), confidence_score NUMERIC(4, 3), content_hash VARCHAR(64), status VARCHAR(10) NOT NULL DEFAULT 'PENDING', target_topic_id BIGINT REFERENCES study_track.topics (id) ON DELETE SET NULL, created_question_id BIGINT REFERENCES study_track.questions (id) ON DELETE SET NULL, sort_order INT NOT NULL DEFAULT 0, CONSTRAINT ck_import_drafts_type CHECK (question_type IN ('QUESTION', 'NOTE', 'EXAMPLE', 'DIAGRAM')), CONSTRAINT ck_import_drafts_difficulty CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')), CONSTRAINT ck_import_drafts_status CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'EDITED', 'DUPLICATE')), CONSTRAINT ck_import_drafts_confidence CHECK (confidence_score IS NULL OR confidence_score BETWEEN 0 AND 1));
CREATE INDEX idx_import_drafts_import_job_id ON study_track.import_drafts (import_job_id, sort_order);
ALTER TABLE study_track.questions ADD CONSTRAINT fk_questions_import_job FOREIGN KEY (import_job_id) REFERENCES study_track.import_jobs (id) ON DELETE SET NULL;
-- V7__create_llm_settings.sql
CREATE TABLE study_track.llm_settings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES study_track.users (id), provider VARCHAR(20) NOT NULL, model VARCHAR(100) NOT NULL, base_url VARCHAR(500), enabled BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_llm_settings_user UNIQUE (user_id), CONSTRAINT ck_llm_settings_provider CHECK (provider IN ('ANTHROPIC', 'OPENAI', 'GROQ', 'OLLAMA')));
-- V8__add_item_search.sql
-- PostgreSQL only: H2 has no tsvector, so questions.search_vector and its GIN index are not created here.
-- On H2, ItemSearchRepository falls back to LIKE matching (see its Javadoc).
-- V10__move_to_study_track_schema.sql: every table above is created in study_track with the V10 names.
-- V11__allow_csv_imports.sql: CSV file type; llm_provider and llm_model nullable (above).
-- V12__link_questions_to_subject_and_user.sql: questions.subject_id and questions.user_id (above).
CREATE INDEX idx_questions_subject_id ON study_track.questions (subject_id, sort_order);
CREATE INDEX idx_questions_user_id ON study_track.questions (user_id);
-- V13__import_drafts_duplicate_status.sql: DUPLICATE draft status (above).
-- V14__create_catalog.sql (users.is_admin is in the users table above)
CREATE TABLE study_track.catalog_tracks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, description VARCHAR(1000), sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_catalog_tracks_name UNIQUE (name));
CREATE TABLE study_track.catalog_subjects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, track_id BIGINT NOT NULL REFERENCES study_track.catalog_tracks (id) ON DELETE CASCADE, name VARCHAR(120) NOT NULL, description VARCHAR(1000), icon VARCHAR(16), sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_catalog_subjects_track_name UNIQUE (track_id, name));
CREATE INDEX idx_catalog_subjects_track_id ON study_track.catalog_subjects (track_id);
CREATE TABLE study_track.catalog_topics (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, catalog_subject_id BIGINT NOT NULL REFERENCES study_track.catalog_subjects (id) ON DELETE CASCADE, parent_id BIGINT REFERENCES study_track.catalog_topics (id) ON DELETE CASCADE, name VARCHAR(200) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_catalog_topics_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id));
CREATE INDEX idx_catalog_topics_subject_id ON study_track.catalog_topics (catalog_subject_id);
CREATE INDEX idx_catalog_topics_parent_id ON study_track.catalog_topics (parent_id);
ALTER TABLE study_track.subjects ADD COLUMN catalog_subject_id BIGINT REFERENCES study_track.catalog_subjects (id) ON DELETE SET NULL;
CREATE INDEX idx_subjects_catalog_subject_id ON study_track.subjects (catalog_subject_id);
